<script setup lang="ts">
import {ref,watch,computed} from 'vue'
import {api,APIError,t,lang,type MenuItem} from '../api'
const props=defineProps<{organizationId:number}>()
const items=ref<MenuItem[]>([]),busy=ref(false),error=ref(''),notice=ref('');let revision=0
async function run(action:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await action()}catch(e){error.value=e instanceof APIError&&Object.keys(e.fields).length?Object.values(e.fields).join(' '):(e as Error).message}finally{busy.value=false}}
watch(()=>props.organizationId,()=>{const id=props.organizationId,rev=++revision;items.value=[];run(async()=>{const loaded=await api<MenuItem[]>(`/admin/menu?organization_id=${id}`);if(rev===revision)items.value=loaded.map(item=>({...item,parent:item.parent||''}))})},{immediate:true})
const rows=computed(()=>{const result:{item:MenuItem;depth:number;path:string}[]=[];function walk(parent='',depth=0,prefix=''){if(depth>=3)return;items.value.filter(item=>(item.parent||'')===parent).forEach((item,index)=>{const path=prefix+(index+1);result.push({item,depth,path});walk(item.key,depth+1,path+'.')})}walk();return result})
function siblings(item:MenuItem){return items.value.filter(other=>(other.parent||'')===(item.parent||''))}
function move(item:MenuItem,step:number){const adjacent=siblings(item),target=adjacent[adjacent.indexOf(item)+step];if(!target)return;const from=items.value.indexOf(item),to=items.value.indexOf(target);[items.value[from],items.value[to]]=[items.value[to],items.value[from]];notice.value=''}
function canParent(item:MenuItem,parent:string){const map=new Map(items.value.map(other=>[other.key,other]));for(const other of items.value){let key=other.key,depth=0;const seen=new Set<string>();while(key){if(seen.has(key)||++depth>3)return false;seen.add(key);const node=map.get(key);if(!node)return false;key=key===item.key?parent:node.parent||''}}return true}
function addLink(){items.value.push({key:'link-'+crypto.randomUUID(),label:{kk:'Жаңа сілтеме',ru:'Новая ссылка'},visible:true,parent:'',url:''});notice.value=''}
function addGroup(){items.value.push({key:'group-'+crypto.randomUUID(),label:{kk:'Жаңа бөлім',ru:'Новый раздел'},visible:true,group:true,parent:''});notice.value=''}
function removeGroup(group:MenuItem){for(const item of items.value)if(item.parent===group.key)item.parent=group.parent||'';items.value=items.value.filter(item=>item.key!==group.key);notice.value=''}
async function save(){items.value=(await api<MenuItem[]>(`/admin/menu?organization_id=${props.organizationId}`,{method:'PUT',body:JSON.stringify(items.value)})).map(item=>({...item,parent:item.parent||''}));notice.value=t('Мәзір сақталды','Меню сохранено')}
</script>
<template><section class="editor-card"><div class="section-heading"><div><p class="eyebrow">{{t('САЙТ НАВИГАЦИЯСЫ','НАВИГАЦИЯ САЙТА')}}</p><h1>{{t('Мәзір құрылымы','Структура меню')}}</h1></div><div class="actions"><button type="button" :disabled="busy||!items.length||items.length>=50" @click="addLink">+ {{t('Сілтеме қосу','Добавить ссылку')}}</button><button type="button" :disabled="busy||!items.length||items.length>=50" @click="addGroup">+ {{t('Бөлім қосу','Добавить группу')}}</button></div></div><p class="quiet">{{t('Үш деңгейге дейін. Атауларды өзгертіп, ата-ана бөлімін таңдаңыз. Көрсеткілер бір бөлім ішіндегі ретті өзгертеді.','До трёх уровней. Изменяйте названия и выбирайте родительскую группу. Стрелки меняют порядок внутри группы.')}}</p><p v-if="error" class="notice" role="alert">{{error}}</p><p v-if="notice" class="success" role="status">{{notice}}</p><form @submit.prevent="run(save)"><div v-for="row in rows" :key="row.item.key" class="menu-row nested-menu-row" :class="{'menu-folder-row':row.item.group}" :style="{'--menu-depth':row.depth}"><span class="menu-index">{{row.path}}</span><div class="menu-fields"><div class="menu-labels"><label>ҚАЗ<input v-model="row.item.label.kk" required :disabled="busy"></label><label>РУС<input v-model="row.item.label.ru" required :disabled="busy"></label></div><label v-if="!row.item.group">{{t('URL мекенжайы','URL-адрес')}}<input v-model="row.item.url" :placeholder="row.item.key.startsWith('link-')?'/news немесе https://example.kz':'/'+(row.item.key==='home'?'':row.item.key)" :required="row.item.key.startsWith('link-')" maxlength="2048" :disabled="busy"><small class="quiet">{{t('Сайт жолы / немесе толық https:// мекенжайы. Бос болса — стандартты бөлім.',row.item.key.startsWith('link-')?'Путь от / или полный адрес https://.':'Путь от / или полный адрес https://. Пустое поле — стандартный раздел.')}}</small></label><div class="menu-placement"><label>{{t('Ата-ана бөлімі','Родительская группа')}}<select v-model="row.item.parent" :disabled="busy||row.item.key==='home'" @change="notice='' "><option value="">{{t('Жоғарғы деңгей','Верхний уровень')}}</option><option v-for="group in items.filter(item=>item.group&&item.key!==row.item.key)" :key="group.key" :value="group.key" :disabled="!canParent(row.item,group.key)">{{group.label[lang]}}</option></select></label><small class="quiet">{{row.item.group?t('Бөлім · ашылмалы мәзір','Группа · раскрывающееся меню'):(row.item.url||(row.item.key.startsWith('link-')?'URL':'/'+(row.item.key==='home'?'':row.item.key)))}}</small></div></div><div class="menu-controls"><label class="check"><input type="checkbox" v-model="row.item.visible" :disabled="busy||row.item.key==='home'">{{t('Көрсету','Показывать')}}</label><div class="move-controls"><button type="button" :disabled="busy||siblings(row.item)[0]===row.item" :aria-label="t('Жоғары жылжыту: ','Переместить выше: ')+row.item.label[lang]" @click="move(row.item,-1)">↑</button><button type="button" :disabled="busy||siblings(row.item).at(-1)===row.item" :aria-label="t('Төмен жылжыту: ','Переместить ниже: ')+row.item.label[lang]" @click="move(row.item,1)">↓</button></div><button v-if="row.item.group||row.item.key.startsWith('link-')" type="button" class="quiet" :disabled="busy" @click="removeGroup(row.item)">{{row.item.group?t('Топты алып тастау','Убрать группу'):t('Сілтемені жою','Удалить ссылку')}}</button></div></div><p class="quiet">{{t('Жасырын бөлім ішіндегі пункттер де жасырын болады. Топты алып тастау беттерді жоймайды.','Скрытая группа скрывает вложенные пункты. При удалении группы её пункты переходят на уровень выше; страницы сохраняются.')}}</p><div class="actions"><button class="primary-button" :disabled="busy||!items.length">{{busy?t('Сақталуда…','Сохранение…'):t('Мәзірді сақтау','Сохранить меню')}}</button></div></form></section></template>
